'use strict';

/**
 * Pure aggregation of the accreditation indicators (no database, no I/O).
 * The repository feeds it with rows read from PostgreSQL and stores the result in MongoDB.
 *
 * Statuses are expected already translated to the English domain values
 * (practice: active | completed | cancelled).
 */

const PASS_GRADE = 3;
/** Version of the stored document shape. Documents without it were generated by the first (summary only) version. */
const INDICATOR_VERSION = 2;

const GRADE_RANGES = Object.freeze([
  { range: '4.0-5.0', test: (g) => g >= 4 },
  { range: '3.0-3.9', test: (g) => g >= 3 && g < 4 },
  { range: '0.1-2.9', test: (g) => g > 0 && g < 3 }
]);

const num = (value) => { const n = Number(value); return Number.isFinite(n) ? n : 0; };
const round = (n, decimals = 1) => { const f = 10 ** decimals; return Math.round(n * f) / f; };
const percent = (part, total) => (total ? round((100 * part) / total, 1) : 0);
const mean = (list) => (list.length ? round(list.reduce((s, x) => s + x, 0) / list.length, 2) : 0);
const sum = (list, pick) => list.reduce((s, x) => s + num(pick(x)), 0);
const toDay = (value) => (value instanceof Date ? value.toISOString().slice(0, 10) : String(value ?? '').slice(0, 10));

function groupBy(list, keyOf) {
  const map = new Map();
  for (const item of list) {
    const key = keyOf(item);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(item);
  }
  return map;
}

/** Whole days between two 'YYYY-MM-DD' dates (null when one of them is not a valid date). */
function daysBetween(start, end) {
  const a = Date.parse(toDay(start));
  const b = Date.parse(toDay(end));
  return Number.isNaN(a) || Number.isNaN(b) ? null : Math.round((b - a) / 86400000);
}

/** ['2025-11', ..., '2026-10'] (oldest first). */
function lastMonths(now = new Date(), count = 12) {
  const out = [];
  let year = now.getFullYear();
  let month = now.getMonth();
  for (let i = 0; i < count; i++) {
    out.push(`${year}-${String(month + 1).padStart(2, '0')}`);
    month -= 1;
    if (month < 0) { month = 11; year -= 1; }
  }
  return out.reverse();
}

/** Puts `rows` ({month, ...counts}) on the given month axis, filling missing months with zeros. */
function fillMonths(rows, months, keys) {
  const byMonth = new Map(rows.map((r) => [r.month, r]));
  return months.map((month) => {
    const row = byMonth.get(month) || {};
    return { month, ...Object.fromEntries(keys.map((k) => [k, num(row[k])])) };
  });
}

/** One practice row (as read from the database) -> the detail kept in the accreditation document. */
function toDetail(row) {
  const finalGrade = num(row.finalGrade);
  return {
    practiceId: row.id,
    studentDocument: row.studentDocument,
    studentDocumentType: row.studentDocumentType || null,
    studentName: row.studentName,
    studentEmail: row.studentEmail || null,
    studentStatus: row.studentStatus || null,
    typeId: row.typeId ?? null,
    type: row.typeName || 'No type',
    taxId: row.taxId ?? null,
    institution: row.institutionName || 'No institution',
    tutorDocument: row.tutorDocument || null,
    tutor: row.tutorName || null,
    advisorDocument: row.advisorDocument || null,
    advisor: row.advisorName || null,
    startDate: toDay(row.startDate),
    endDate: toDay(row.endDate),
    status: row.status,
    finalGrade: finalGrade > 0 ? finalGrade : null,
    finalObservation: String(row.finalObservation || '').trim() || null,
    requiredHours: num(row.requiredHours),
    loggedHours: num(row.hours),
    activities: num(row.activities),
    evidences: num(row.evidences),
    tutorFeedback: num(row.tutorFeedback),
    advisorFeedback: num(row.advisorFeedback),
    durationDays: daysBetween(row.startDate, row.endDate)
  };
}

const gradedOf = (details) => details.filter((d) => d.finalGrade !== null);
const approvedOf = (graded) => graded.filter((d) => d.finalGrade >= PASS_GRADE);

function summarize(details) {
  const graded = gradedOf(details);
  const grades = graded.map((d) => d.finalGrade);
  const approved = approvedOf(graded).length;
  const requiredHours = sum(details.filter((d) => d.status !== 'cancelled'), (d) => d.requiredHours);
  const loggedHours = sum(details.filter((d) => d.status !== 'cancelled'), (d) => d.loggedHours);
  return {
    practices: details.length,
    active: details.filter((d) => d.status === 'active').length,
    completed: details.filter((d) => d.status === 'completed').length,
    cancelled: details.filter((d) => d.status === 'cancelled').length,
    graded: graded.length,
    ungraded: details.length - graded.length,
    averageGrade: mean(grades),
    minGrade: grades.length ? Math.min(...grades) : 0,
    maxGrade: grades.length ? Math.max(...grades) : 0,
    approved,
    failed: graded.length - approved,
    approvalRate: percent(approved, graded.length),
    requiredHours,
    loggedHours,
    hoursCompletion: percent(loggedHours, requiredHours),
    activities: sum(details, (d) => d.activities),
    evidences: sum(details, (d) => d.evidences)
  };
}

function byType(details) {
  return [...groupBy(details, (d) => d.typeId ?? d.type).values()].map((group) => {
    const graded = gradedOf(group);
    return {
      typeId: group[0].typeId,
      type: group[0].type,
      requiredHours: group[0].requiredHours,
      count: group.length,
      students: new Set(group.map((d) => d.studentDocument)).size,
      averageGrade: mean(graded.map((d) => d.finalGrade)),
      approvalRate: percent(approvedOf(graded).length, graded.length)
    };
  }).sort((a, b) => b.count - a.count || a.type.localeCompare(b.type));
}

function byInstitution(details) {
  return [...groupBy(details, (d) => d.taxId ?? d.institution).values()].map((group) => ({
    taxId: group[0].taxId,
    institutionName: group[0].institution,
    practiceCount: group.length,
    studentCount: new Set(group.map((d) => d.studentDocument)).size,
    activeCount: group.filter((d) => d.status === 'active').length,
    completedCount: group.filter((d) => d.status === 'completed').length,
    averageGrade: mean(gradedOf(group).map((d) => d.finalGrade))
  })).sort((a, b) => b.practiceCount - a.practiceCount || a.institutionName.localeCompare(b.institutionName));
}

/** Tutors or advisors: `role` = 'tutor' | 'advisor'. */
function byTeacher(details, role) {
  const documentKey = `${role}Document`;
  const feedbackKey = `${role}Feedback`;
  return [...groupBy(details.filter((d) => d[documentKey]), (d) => d[documentKey]).values()].map((group) => ({
    document: group[0][documentKey],
    name: group[0][role],
    practices: group.length,
    students: new Set(group.map((d) => d.studentDocument)).size,
    activePractices: group.filter((d) => d.status === 'active').length,
    feedbackCount: sum(group, (d) => d[feedbackKey]),
    averageGrade: mean(gradedOf(group).map((d) => d.finalGrade))
  })).sort((a, b) => b.practices - a.practices || String(a.name).localeCompare(String(b.name)));
}

/**
 * @param {{id, name, faculty, totalStudents, activeStudents, activeTutors}} program
 * @param {object[]} rows  practice rows of that program in `year`
 */
function indicatorFor(program, rows, year, generatedAt) {
  const details = rows.map(toDetail);
  const graded = gradedOf(details);
  const tutorFeedback = sum(details, (d) => d.tutorFeedback);
  const advisorFeedback = sum(details, (d) => d.advisorFeedback);
  const durations = details.map((d) => d.durationDays).filter((d) => d !== null);
  const tutors = byTeacher(details, 'tutor');
  const advisors = byTeacher(details, 'advisor');

  // emails live on the user tables; they are attached by the repository when available
  const emailOf = (list, key) => new Map(rows.map((r) => [r[key.document], r[key.email]]));
  const tutorEmails = emailOf(rows, { document: 'tutorDocument', email: 'tutorEmail' });
  const advisorEmails = emailOf(rows, { document: 'advisorDocument', email: 'advisorEmail' });
  tutors.forEach((t) => { t.email = tutorEmails.get(t.document) || null; });
  advisors.forEach((a) => { a.email = advisorEmails.get(a.document) || null; });

  const institutions = byInstitution(details);
  const institutionData = new Map(rows.map((r) => [r.taxId ?? r.institutionName, r]));
  institutions.forEach((i) => {
    const source = institutionData.get(i.taxId ?? i.institutionName) || {};
    i.address = source.institutionAddress || null;
    i.manager = source.institutionManager || null;
    i.email = source.institutionEmail || null;
  });

  return {
    year,
    programId: program.id,
    programName: program.name,
    faculty: program.faculty || null,
    version: INDICATOR_VERSION,
    generatedAt,
    totalStudents: num(program.totalStudents),
    activeStudentsTotal: num(program.activeStudents),
    activeTutors: num(program.activeTutors),
    summary: summarize(details),
    practicesByType: byType(details),
    gradeDistribution: GRADE_RANGES.map(({ range, test }) => ({
      range, studentCount: graded.filter((d) => test(d.finalGrade)).length
    })),
    teacherSupport: {
      tutorFeedbackCount: tutorFeedback,
      advisorFeedbackCount: advisorFeedback,
      practicesWithoutTutorFeedback: details.filter((d) => d.tutorFeedback === 0).length,
      practicesWithoutAdvisorFeedback: details.filter((d) => d.advisorFeedback === 0).length,
      feedbackPerPractice: details.length ? round((tutorFeedback + advisorFeedback) / details.length, 1) : 0
    },
    partnerInstitutions: institutions,
    tutors,
    advisors,
    practices: details,
    dropoutRate: percent(details.filter((d) => d.status === 'cancelled').length, details.length),
    averagePracticeDurationDays: durations.length ? Math.round(durations.reduce((s, d) => s + d, 0) / durations.length) : 0
  };
}

/**
 * @param {{year: number, programs: object[], practices: object[], generatedAt?: string}} input
 *   practices: rows with `programId`, `status` (English) and the columns used by toDetail()
 * @returns {object[]} one indicator per program (programs without practices still get one, with zeros)
 */
function buildIndicators({ year, programs, practices, generatedAt = new Date().toISOString() }) {
  const byProgram = groupBy(practices, (p) => p.programId);
  return programs.map((program) => indicatorFor(program, byProgram.get(program.id) || [], year, generatedAt));
}

module.exports = {
  PASS_GRADE, INDICATOR_VERSION, GRADE_RANGES, buildIndicators, toDetail, lastMonths, fillMonths, daysBetween, percent, mean
};
